extension Navree {
    /// `Call`: one of its variants, told apart by `f`.
    public indirect enum Call: Codable, Hashable, Sendable {
        case haptic(Navree.Haptic)
        case copy(Navree.CopyText)
        case share(Navree.Share)
        case openUrl(Navree.OpenUrl)
        case authSession(Navree.AuthSession)
        case registerPush(Navree.RegisterPush)
        case notify(Navree.Notify)
        case cancelNotification(Navree.CancelNotification)
        case setBadge(Navree.SetBadge)
        case openSettings(Navree.OpenSettings)
        case passkey(Navree.Passkey)
        case confirm(Navree.Confirm)
        case locateOnce(Navree.LocateOnce)
        case scanCode(Navree.ScanCode)
        case platformSignIn(Navree.PlatformSignIn)
        /// A variant this build does not know, from a newer server, with what it keeps.
        case unknown(Navree.Call.Unknown)

        private enum TagKey: String, CodingKey {
            case tag = "f"
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: TagKey.self)
            let tag = (try? container.decodeIfPresent(String.self, forKey: .tag)) ?? ""
            switch tag {
            case "haptic": self = .haptic(try Navree.Haptic(from: decoder))
            case "copy": self = .copy(try Navree.CopyText(from: decoder))
            case "share": self = .share(try Navree.Share(from: decoder))
            case "open_url": self = .openUrl(try Navree.OpenUrl(from: decoder))
            case "auth_session": self = .authSession(try Navree.AuthSession(from: decoder))
            case "register_push": self = .registerPush(try Navree.RegisterPush(from: decoder))
            case "notify": self = .notify(try Navree.Notify(from: decoder))
            case "cancel_notification": self = .cancelNotification(try Navree.CancelNotification(from: decoder))
            case "set_badge": self = .setBadge(try Navree.SetBadge(from: decoder))
            case "open_settings": self = .openSettings(try Navree.OpenSettings(from: decoder))
            case "passkey": self = .passkey(try Navree.Passkey(from: decoder))
            case "confirm": self = .confirm(try Navree.Confirm(from: decoder))
            case "locate_once": self = .locateOnce(try Navree.LocateOnce(from: decoder))
            case "scan_code": self = .scanCode(try Navree.ScanCode(from: decoder))
            case "platform_sign_in": self = .platformSignIn(try Navree.PlatformSignIn(from: decoder))
            default: self = .unknown(try Navree.Call.Unknown(from: decoder, tag: tag))
            }
        }

        public func encode(to encoder: any Encoder) throws {
            var container = encoder.container(keyedBy: TagKey.self)
            switch self {
            case .haptic(let value):
                try container.encode("haptic", forKey: .tag)
                try value.encode(to: encoder)
            case .copy(let value):
                try container.encode("copy", forKey: .tag)
                try value.encode(to: encoder)
            case .share(let value):
                try container.encode("share", forKey: .tag)
                try value.encode(to: encoder)
            case .openUrl(let value):
                try container.encode("open_url", forKey: .tag)
                try value.encode(to: encoder)
            case .authSession(let value):
                try container.encode("auth_session", forKey: .tag)
                try value.encode(to: encoder)
            case .registerPush(let value):
                try container.encode("register_push", forKey: .tag)
                try value.encode(to: encoder)
            case .notify(let value):
                try container.encode("notify", forKey: .tag)
                try value.encode(to: encoder)
            case .cancelNotification(let value):
                try container.encode("cancel_notification", forKey: .tag)
                try value.encode(to: encoder)
            case .setBadge(let value):
                try container.encode("set_badge", forKey: .tag)
                try value.encode(to: encoder)
            case .openSettings(let value):
                try container.encode("open_settings", forKey: .tag)
                try value.encode(to: encoder)
            case .passkey(let value):
                try container.encode("passkey", forKey: .tag)
                try value.encode(to: encoder)
            case .confirm(let value):
                try container.encode("confirm", forKey: .tag)
                try value.encode(to: encoder)
            case .locateOnce(let value):
                try container.encode("locate_once", forKey: .tag)
                try value.encode(to: encoder)
            case .scanCode(let value):
                try container.encode("scan_code", forKey: .tag)
                try value.encode(to: encoder)
            case .platformSignIn(let value):
                try container.encode("platform_sign_in", forKey: .tag)
                try value.encode(to: encoder)
            case .unknown(let value):
                try container.encode(value.tag, forKey: .tag)
                try value.encode(to: encoder)
            }
        }
    }
}

