        case text(Navree.TextInput)
        case toggle(Navree.ToggleInput)
        case choice(Navree.ChoiceInput)
        case choices(Navree.ChoicesInput)
        case date(Navree.DateInput)
        case slider(Navree.SliderInput)
        case colour(Navree.ColourInput)
        case file(Navree.FileInput)
