            let container = try decoder.container(keyedBy: TagKey.self)
            let tag = (try? container.decodeIfPresent(String.self, forKey: .tag)) ?? ""
            switch tag {
            case "text": self = .text(try Navree.TextInput(from: decoder))
            case "toggle": self = .toggle(try Navree.ToggleInput(from: decoder))
            case "choice": self = .choice(try Navree.ChoiceInput(from: decoder))
            case "choices": self = .choices(try Navree.ChoicesInput(from: decoder))
            case "date": self = .date(try Navree.DateInput(from: decoder))
            case "slider": self = .slider(try Navree.SliderInput(from: decoder))
            case "colour": self = .colour(try Navree.ColourInput(from: decoder))
            case "file": self = .file(try Navree.FileInput(from: decoder))
            case "range": self = .range(try Navree.RangeInput(from: decoder))
            default: self = .unknown(try Navree.Input.Unknown(from: decoder, tag: tag))
            }
        }

        public func encode(to encoder: any Encoder) throws {
            var container = encoder.container(keyedBy: TagKey.self)
            switch self {
            case .text(let value):
                try container.encode("text", forKey: .tag)
                try value.encode(to: encoder)
            case .toggle(let value):
                try container.encode("toggle", forKey: .tag)
                try value.encode(to: encoder)
            case .choice(let value):
                try container.encode("choice", forKey: .tag)
                try value.encode(to: encoder)
            case .choices(let value):
                try container.encode("choices", forKey: .tag)
                try value.encode(to: encoder)
            case .date(let value):
                try container.encode("date", forKey: .tag)
                try value.encode(to: encoder)
            case .slider(let value):
                try container.encode("slider", forKey: .tag)
                try value.encode(to: encoder)
            case .colour(let value):
                try container.encode("colour", forKey: .tag)
                try value.encode(to: encoder)
            case .file(let value):
                try container.encode("file", forKey: .tag)
                try value.encode(to: encoder)
            case .range(let value):
                try container.encode("range", forKey: .tag)
                try value.encode(to: encoder)
            case .unknown(let value):
