extension Navree {
    /// `ReplyCall`: one of its variants, told apart by `f`.
    public indirect enum ReplyCall: Codable, Hashable, Sendable {
        case haptic(Navree.Haptic)
        case setBadge(Navree.SetBadge)
        case cancelNotification(Navree.CancelNotification)
        case requestReview
        /// A variant this build does not know, from a newer server, with what it keeps.
        case unknown(Navree.ReplyCall.Unknown)

        private enum TagKey: String, CodingKey {
            case tag = "f"
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: TagKey.self)
            let tag = (try? container.decodeIfPresent(String.self, forKey: .tag)) ?? ""
            switch tag {
            case "haptic": self = .haptic(try Navree.Haptic(from: decoder))
            case "set_badge": self = .setBadge(try Navree.SetBadge(from: decoder))
            case "cancel_notification": self = .cancelNotification(try Navree.CancelNotification(from: decoder))
            case "request_review": self = .requestReview
            default: self = .unknown(try Navree.ReplyCall.Unknown(from: decoder, tag: tag))
            }
        }

        public func encode(to encoder: any Encoder) throws {
            var container = encoder.container(keyedBy: TagKey.self)
            switch self {
            case .haptic(let value):
                try container.encode("haptic", forKey: .tag)
                try value.encode(to: encoder)
            case .setBadge(let value):
                try container.encode("set_badge", forKey: .tag)
                try value.encode(to: encoder)
            case .cancelNotification(let value):
                try container.encode("cancel_notification", forKey: .tag)
                try value.encode(to: encoder)
            case .requestReview:
                try container.encode("request_review", forKey: .tag)
            case .unknown(let value):
                try container.encode(value.tag, forKey: .tag)
                try value.encode(to: encoder)
            }
        }
    }
}

