extension Navree {
    /// `When`: one of its variants, told apart by `t`.
    public indirect enum When: Codable, Hashable, Sendable {
        case at(Navree.When.At)
        case after(Navree.When.After)
        case daily(Navree.When.Daily)
        /// A variant this build does not know, from a newer server, with what it keeps.
        case unknown(Navree.When.Unknown)

        private enum TagKey: String, CodingKey {
            case tag = "t"
        }

        public init(from decoder: any Decoder) throws {
            let container = try decoder.container(keyedBy: TagKey.self)
            let tag = (try? container.decodeIfPresent(String.self, forKey: .tag)) ?? ""
            switch tag {
            case "at": self = .at(try Navree.When.At(from: decoder))
            case "after": self = .after(try Navree.When.After(from: decoder))
            case "daily": self = .daily(try Navree.When.Daily(from: decoder))
            default: self = .unknown(try Navree.When.Unknown(from: decoder, tag: tag))
            }
        }

        public func encode(to encoder: any Encoder) throws {
            var container = encoder.container(keyedBy: TagKey.self)
            switch self {
            case .at(let value):
                try container.encode("at", forKey: .tag)
                try value.encode(to: encoder)
            case .after(let value):
                try container.encode("after", forKey: .tag)
                try value.encode(to: encoder)
            case .daily(let value):
                try container.encode("daily", forKey: .tag)
                try value.encode(to: encoder)
            case .unknown(let value):
                try container.encode(value.tag, forKey: .tag)
                try value.encode(to: encoder)
            }
        }
    }
}

extension Navree.When {
    /// A variant of `When` this build does not know: its tag, and what it keeps.
    public struct Unknown: Hashable, Sendable {
        public var tag: String

        public init(tag: String) {
            self.tag = tag
        }

        init(from decoder: any Decoder, tag: String) throws {
            self.tag = tag
        }

        func encode(to encoder: any Encoder) throws {}
    }
}

